package com.sugarplumstudios.pinkified.client.gui;

import com.sugarplumstudios.pinkified.client.theme.ThemeId;
import com.sugarplumstudios.pinkified.client.util.Ids;
import net.minecraft.resources.ResourceLocation;

/** Locations of Pinkified's own static textures (all generated by tools/assetgen). */
public final class PinkTextures {
    private PinkTextures() {
    }

    private static ResourceLocation tex(String path) {
        return Ids.mod("textures/" + path + ".png");
    }

    public static final ResourceLocation[] PETALS = {
            tex("gui/menu/petal_0"), tex("gui/menu/petal_1"), tex("gui/menu/petal_2"), tex("gui/menu/petal_3")};
    public static final int[][] PETAL_SIZES = {{7, 8}, {7, 7}, {5, 5}, {7, 8}};
    public static final ResourceLocation SPARKLE_BIG = tex("gui/menu/sparkle_big");
    public static final ResourceLocation SPARKLE_SMALL = tex("gui/menu/sparkle_small");
    public static final ResourceLocation HEART = tex("gui/menu/heart");
    public static final ResourceLocation BOW = tex("gui/menu/bow");
    public static final ResourceLocation BOKEH = tex("gui/menu/bokeh");
    public static final ResourceLocation[] CLOUDS = {tex("gui/menu/cloud_0"), tex("gui/menu/cloud_1")};
    public static final ResourceLocation LOGO_BASE = tex("gui/logo/pinkified_base");
    public static final ResourceLocation LOGO_GLOSS = tex("gui/logo/pinkified_gloss");
    public static final int LOGO_W = 104, LOGO_H = 29;

    public static final ResourceLocation TAB_THEME = tex("gui/icons/tab_theme");
    public static final ResourceLocation TAB_INTERFACE = tex("gui/icons/tab_interface");
    public static final ResourceLocation TAB_HUD = tex("gui/icons/tab_hud");
    public static final ResourceLocation TAB_EFFECTS = tex("gui/icons/tab_effects");
    public static final ResourceLocation TAB_MOTION = tex("gui/icons/tab_motion");
    public static final ResourceLocation TAB_AUDIO = tex("gui/icons/tab_audio");
    public static final ResourceLocation HEART_BUTTON = tex("gui/icons/heart_button");
    public static final ResourceLocation LANGUAGE = tex("gui/icons/language");
    public static final ResourceLocation ACCESSIBILITY = tex("gui/icons/accessibility");

    public static ResourceLocation themeIcon(ThemeId id) {
        return Ids.mod(id.iconPath());
    }
}
